import urllib.request, xml.etree.ElementTree as ET, email.utils, datetime as dt, re
from urllib.parse import unquote
UA='Mozilla/5.0 (compatible; OpenClawScout/1.0)'
feeds=[
('CoinDesk','https://www.coindesk.com/arc/outboundfeeds/rss/'),
('CoinTelegraph','https://cointelegraph.com/rss'),
('Decrypt','https://decrypt.co/feed'),
('Google News','https://news.google.com/rss/search?q=cryptocurrency+OR+blockchain+OR+ethereum+OR+solana+OR+altcoin+OR+%22digital+assets%22+OR+XRP+OR+cardano+-dogecoin+-shiba+-pepe+-floki+-bonk+-wif+-memecoin+-%22meme+coin%22&hl=en-US&gl=US&ceid=US:en'),
('BeInCrypto','https://beincrypto.com/feed/'),
('The Block','https://www.theblock.co/rss.xml'),
('CryptoSlate','https://cryptoslate.com/feed/'),
('CryptoFox Markets','https://cryptofox.news/rss/markets/'),
('CryptoFox Regulation','https://cryptofox.news/rss/regulation/'),
]
now=dt.datetime.now(dt.timezone.utc)
cutoff=now-dt.timedelta(days=1)
ns={'atom':'http://www.w3.org/2005/Atom','content':'http://purl.org/rss/1.0/modules/content/'}

def get(url):
    req=urllib.request.Request(url, headers={'User-Agent':UA})
    with urllib.request.urlopen(req, timeout=20) as r:
        return r.read()

def text(el, *names):
    for name in names:
        found=el.find(name, ns)
        if found is not None and found.text:
            return found.text.strip()
    return ''

for name,url in feeds:
    try:
        data=get(url)
        root=ET.fromstring(data)
    except Exception as e:
        print(f'## {name} ERROR {e}')
        continue
    items=[]
    if root.tag.endswith('feed'):
        entries=root.findall('atom:entry', ns) or root.findall('{http://www.w3.org/2005/Atom}entry')
        for it in entries:
            title=text(it,'atom:title','title')
            link=''
            l=it.find('atom:link',ns)
            if l is not None:
                link=l.attrib.get('href','')
            pub=text(it,'atom:updated','atom:published','updated','published')
            items.append((title,link,pub))
    else:
        channel=root.find('channel')
        if channel is None:
            entries=root.findall('.//item')
        else:
            entries=channel.findall('item')
        for it in entries:
            title=text(it,'title')
            link=text(it,'link')
            pub=text(it,'pubDate','date')
            items.append((title,link,pub))
    todays=[]
    for title,link,pub in items[:25]:
        try:
            d=email.utils.parsedate_to_datetime(pub)
            if d.tzinfo is None: d=d.replace(tzinfo=dt.timezone.utc)
            d=d.astimezone(dt.timezone.utc)
        except Exception:
            d=None
        if d and d>=cutoff:
            todays.append((d,title,link))
    print(f'## {name} ({len(todays)} last24h)')
    for d,title,link in todays[:8]:
        print(d.strftime('%Y-%m-%d %H:%M'), '|', title[:140], '|', link)
    print()
PY
